Sure, here is a simple implementation of an AXI4-Lite clock-domain bridge in Verilog-2001. This implementation assumes that the two clock domains are independent and that the reset signals are active-high.

```
module axil_cdc #
(
    parameter DATA_WIDTH = 32,
    parameter ADDR_WIDTH = 32,
    parameter STRB_WIDTH = (DATA_WIDTH/8)
)
(
    /*
     * AXI lite slave interface
     */
    input  wire                   s_clk,
    input  wire                   s_rst,
    input  wire [ADDR_WIDTH-1:0]  s_axil_awaddr,
    input  wire [2:0]             s_axil_awprot,
    input  wire                   s_axil_awvalid,
    output wire                   s_axil_awready,
    input  wire [DATA_WIDTH-1:0]  s_axil_wdata,
    input  wire [STRB_WIDTH-1:0]  s_axil_wstrb,
    input  wire                   s_axil_wvalid,
    output wire                   s_axil_wready,
    output wire [1:0]             s_axil_bresp,
    output wire                   s_axil_bvalid,
    input  wire                   s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]  s_axil_araddr,
    input  wire [2:0]             s_axil_arprot,
    input  wire                   s_axil_arvalid,
    output wire                   s_axil_arready,
    output wire [DATA_WIDTH-1:0]  s_axil_rdata,
    output wire [1:0]             s_axil_rresp,
    output wire                   s_axil_rvalid,
    input  wire                   s_axil_rready,
    /*
     * AXI lite master interface
     */
    input  wire                   m_clk,
    input  wire                   m_rst,
    output wire [ADDR_WIDTH-1:0]  m_axil_awaddr,
    output wire [2:0]             m_axil_awprot,
    output wire                   m_axil_awvalid,
    input  wire                   m_axil_awready,
    output wire [DATA_WIDTH-1:0]  m_axil_wdata,
    output wire [STRB_WIDTH-1:0]  m_axil_wstrb,
    output wire                   m_axil_wvalid,
    input  wire                   m_axil_wready,
    input  wire [1:0]             m_axil_bresp,
    input  wire                   m_axil_bvalid,
    output wire                   m_axil_bready,
    output wire [ADDR_WIDTH-1:0]  m_axil_araddr,
    output wire [2:0]             m_axil_arprot,
    output wire                   m_axil_arvalid,
    input  wire                   m_axil_arready,
    input  wire [DATA_WIDTH-1:0]  m_axil_rdata,
    input  wire [1:0]             m_axil_rresp,
    input  wire                   m_axil_rvalid,
    output wire                   m_axil_rready
);

reg [DATA_WIDTH-1:0] rdata_reg;
reg [1:0] rresp_reg;
reg rvalid_reg;

reg [ADDR_WIDTH-1:0] awaddr_reg;
reg [2:0] awprot_reg;
reg awvalid_reg;
reg [DATA_WIDTH-1:0] wdata_reg;
reg [STRB_WIDTH-1:0] wstrb_reg;
reg wvalid_reg;
reg [ADDR_WIDTH-1:0] araddr_reg;
reg [2:0] arprot_reg;
reg arvalid_reg;

always @(posedge s_clk) begin
    if (s_rst) begin
        awvalid_reg <= 1'b0;
        wvalid_reg <= 1'b0;
        arvalid_reg <= 1'b0;
    end else begin
        awvalid_reg <= s_axil_awvalid;
        wvalid_reg <= s_axil_wvalid;
        arvalid_reg <= s_axil_arvalid;
    end
end

always @(posedge s_clk) begin
    if (s_rst) begin
        awaddr_reg <= {ADDR_WIDTH{1'b0}};
        awprot_reg <= 3'b0;
        wdata_reg <= {DATA_WIDTH{1'b0}};
        wstrb_reg <= {STRB_WIDTH{1'b0}};
        araddr_reg <= {ADDR_WIDTH{1'b0}};
        arprot_reg <= 3'b0;
    end else begin
        awaddr_reg <= s_axil_awaddr;
        awprot_reg <= s_axil_awprot;
        wdata_reg <= s_axil_wdata;
        wstrb_reg <= s_axil_wstrb;
        araddr_reg <= s_axil_araddr;
        arprot_reg <= s_axil_arprot;
    end
end

always @(posedge m_clk) begin
    if (m_rst) begin
        rvalid_reg <= 1'b0;
        rdata_reg <= {DATA_WIDTH{1'b0}};
        rresp_reg <= 2'b0;
    end else begin
        if (m_axil_rready && rvalid_reg) begin
            rvalid_reg <= 1'b0;
        end
        if (m_axil_rvalid && !rvalid_reg) begin
            rvalid_reg <= 1'b1;
            rdata_reg <= m_axil_rdata;
            rresp_reg <= m_axil_rresp;
        end
    end
end

assign s_axil_awready = m_axil_awready;
assign s_axil_wready = m_axil_wready;
assign s_axil_arready = m_axil_arready;
assign s_axil_rdata = rdata_reg;
assign s_axil_rresp = rresp_reg;
assign s_axil_rvalid = rvalid_reg;
assign m_axil_awaddr = awaddr_reg;
assign m_axil_awprot = awprot_reg;
assign m_axil_awvalid = awvalid_reg;
assign m_axil_wdata = wdata_reg;
assign m_axil_wstrb = wstrb_reg;
assign m_axil_wvalid = wvalid_reg;
assign m_axil_araddr = araddr_reg;
assign m_axil_arprot = arprot_reg;
assign m_axil_arvalid = arvalid_reg;
assign m_axil_rready = 1'b1;

